    await waitFor(() =>
      expect(result.current.data).toEqual({
        codigo: 'contest-demo',
        mensaje: 'Created',
      }),
    )
    act(() => result.current.reset())
    await waitFor(() => expect(result.current.data).toBeUndefined())
  })
})

